		clear_resets!!.invoke(this.subcatch_evap_mode, this.subcatch_evap_persist)
		clear_resets!!.invoke(this.subcatch_snowfall_mode, this.subcatch_snowfall_persist)
		clear_resets!!.invoke(this.gage_rainfall_mode, this.gage_rainfall_persist)
		if (this.climate_temperature_persist == ForcingPersist.RESET) {
			this.climate_temperature_mode = ForcingMode.NONE
		}
		if (this.climate_wind_persist == ForcingPersist.RESET) {
			this.climate_wind_mode = ForcingMode.NONE
		}
		if (this.climate_evap_persist == ForcingPersist.RESET) {
			this.climate_evap_mode = ForcingMode.NONE
		}
		var k: Int = 0
		__L3@ while (k < 2) {
			(cpp.Ptr<ForcingData_ElemClimateChannel?>(this.elem_air_temp, 0L)).get_Item_i(k)!!.resetPerStep()
			(cpp.Ptr<ForcingData_ElemClimateChannel?>(this.elem_humidity, 0L)).get_Item_i(k)!!.resetPerStep()
			(cpp.Ptr<ForcingData_ElemClimateChannel?>(this.elem_wind, 0L)).get_Item_i(k)!!.resetPerStep()
			(cpp.Ptr<ForcingData_ElemClimateChannel?>(this.elem_shortwave, 0L)).get_Item_i(k)!!.resetPerStep()
			k++
		}
	}

